import numpy as np


class AdaptiveMixedDEArchive:
    """
    Mixed-integer constrained optimiser:
    - stratified (LHS-like) initialisation with restarts,
    - elite-archive based differential evolution (DE/rand/1 and DE/current-to-best style)
      on continuous variables, uniform crossover on discrete variables,
    - Gaussian mutation with 1/5-style success-based step-size adaptation,
    - type-aware discrete mutation (ordinal: local steps, categorical/binary: random relabel),
    - caching of already evaluated points (duplicates cost no budget),
    - restarts when the run stagnates.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng(np.random.randint(0, 2**31 - 1))
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        span = ub - lb
        vtypes = list(func.variable_types)

        nvals = np.ones(dim, dtype=int)
        for i in range(dim):
            if vtypes[i] != "continuous":
                nvals[i] = int(func.n_values[i])

        disc = np.array([i for i in range(dim) if vtypes[i] != "continuous"], dtype=int)
        cont = np.array([i for i in range(dim) if vtypes[i] == "continuous"], dtype=int)
        n_disc = max(len(disc), 1)

        cache = {}
        best = {"y": np.inf, "x": None}
        state = {"n": 0}

        def repair(x):
            x = np.clip(x, lb, ub)
            if disc.size:
                x[disc] = np.clip(np.round(x[disc]), 0, nvals[disc] - 1)
            return x

        def key(x):
            return tuple(np.round(x, 10))

        def ev(x):
            # Only called when state["n"] < budget.
            x = repair(np.array(x, dtype=float))
            k = key(x)
            if k in cache:
                return cache[k], x, False
            y = float(func(x))
            state["n"] += 1
            cache[k] = y
            if y < best["y"]:
                best["y"] = y
                best["x"] = x.copy()
            return y, x, True

        def random_point():
            x = np.zeros(dim)
            if cont.size:
                x[cont] = rng.uniform(lb[cont], ub[cont])
            for j in disc:
                x[j] = rng.integers(0, nvals[j])
            return x

        def init_points(m):
            X = np.zeros((m, dim))
            for j in cont:
                X[:, j] = lb[j] + (rng.permutation(m) + rng.random(m)) / m * span[j]
            for j in disc:
                idx = np.floor((rng.permutation(m) + rng.random(m)) / m * nvals[j])
                X[:, j] = np.clip(idx, 0, nvals[j] - 1)
            return X

        def mutate_disc(x, j):
            n = nvals[j]
            if n <= 1:
                return
            if vtypes[j] == "ordinal" and rng.random() < 0.7:
                step = 1 if rng.random() < 0.5 else -1
                nv = x[j] + step
                if nv < 0 or nv > n - 1:
                    nv = x[j] - step
                x[j] = np.clip(nv, 0, n - 1)
            else:
                v = rng.integers(0, n - 1)
                if v >= x[j]:
                    v += 1
                x[j] = v

        mu = int(np.clip(4 * dim, 10, 50))
        patience = 15 * dim + 40
        tot_iter = 0
        max_iter = 100 * budget + 1000

        while state["n"] < budget and tot_iter < max_iter:
            # ---- (re)start: stratified initial population ----
            n0 = min(max(10, 4 * dim), budget - state["n"])
            if n0 <= 0:
                break
            X0 = init_points(n0)
            pool = []
            for x in X0:
                if state["n"] >= budget:
                    break
                y, xr, _ = ev(x)
                pool.append((y, xr))
            if not pool:
                break
            pool.sort(key=lambda t: t[0])
            pool = pool[:mu]

            sigma = 0.15
            pm = max(1.0 / n_disc, 0.1)
            succ_hist = []
            stall = 0
            local_best = pool[0][0]

            while state["n"] < budget and tot_iter < max_iter:
                tot_iter += 1
                P = len(pool)
                ys = [p[0] for p in pool]
                if P < 2 or rng.random() < 0.05:
                    child = random_point()
                    parent_y = np.inf
                else:
                    a, b = rng.integers(0, P, 2)
                    i = min(a, b)  # pool sorted: lower index is better
                    base = pool[i][1]
                    parent_y = ys[i]
                    if rng.random() < 0.5 and P >= 4:
                        # DE: current-to-best / rand mix
                        if rng.random() < 0.5:
                            r1 = 0
                        else:
                            r1 = rng.integers(0, P)
                        r2 = rng.integers(0, P)
                        tries = 0
                        while (r1 == i or r1 == r2 or r2 == i) and tries < 20:
                            if r1 == i or r1 == r2:
                                r1 = rng.integers(0, P)
                            if r2 == i or r2 == r1:
                                r2 = rng.integers(0, P)
                            tries += 1
                        x1 = pool[r1][1]
                        x2 = pool[r2][1]
                        F = rng.uniform(0.3, 0.9)
                        child = base.copy()
                        if cont.size:
                            mutant = base[cont] + F * (x1[cont] - x2[cont])
                            if rng.random() < 0.5:
                                mutant = mutant + F * (pool[0][1][cont] - base[cont])
                            mask = rng.random(cont.size) < 0.9
                            mask[rng.integers(cont.size)] = True
                            child[cont] = np.where(mask, mutant, base[cont])
                        for j in disc:
                            if rng.random() < 0.5:
                                donor = x1 if rng.random() < 0.5 else x2
                                if rng.random() < 0.9:
                                    child[j] = donor[j]
                    else:
                        # Gaussian mutation on continuous, typed mutation on discrete
                        child = base.copy()
                        changed = False
                        if cont.size:
                            mc = rng.random(cont.size) < max(1.0 / cont.size, 0.3)
                            if mc.any():
                                child[cont[mc]] += rng.normal(0, sigma, mc.sum()) * span[cont[mc]]
                                changed = True
                        for j in disc:
                            if rng.random() < pm:
                                mutate_disc(child, j)
                                changed = True
                        if not changed:
                            j = rng.integers(0, dim)
                            if vtypes[j] == "continuous":
                                child[j] += rng.normal(0, sigma) * span[j]
                            else:
                                mutate_disc(child, j)

                child = repair(child)
                n_before = state["n"]
                y, xr, is_new = ev(child)
                if not is_new:
                    # Duplicate: no budget spent; keep iterating.
                    continue

                # Step-size adaptation (1/5-rule style over windows of 10 evaluations)
                if np.isfinite(parent_y):
                    succ_hist.append(1.0 if y < parent_y else 0.0)
                    if len(succ_hist) >= 10:
                        rate = float(np.mean(succ_hist))
                        sigma *= 1.3 if rate > 0.2 else 0.8
                        sigma = float(np.clip(sigma, 1e-3, 0.3))
                        succ_hist = []

                # Stagnation tracking
                if y < local_best - 1e-12:
                    local_best = y
                    stall = 0
                else:
                    stall += 1

                # Archive / population update
                if len(pool) < mu or y < pool[-1][0]:
                    pool.append((y, xr))
                    pool.sort(key=lambda t: t[0])
                    pool = pool[:mu]

                if stall >= patience:
                    break  # restart with fresh stratified sample

        return best["y"], best["x"]
